package com.gestordevendas.api.food;
import com.gestordevendas.api.common.error.ApiException; import com.gestordevendas.api.common.security.CurrentUserService; import com.gestordevendas.api.company.*; import com.gestordevendas.api.feature.*; import com.gestordevendas.api.product.*; import com.gestordevendas.api.sale.*; import com.gestordevendas.api.tenant.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*;
@Service public class FoodService { @org.springframework.beans.factory.annotation.Autowired private DiningTableRepository diningTables; private final CourierRepository couriers; private final SnackRepository snacks; private final BeverageRepository beverages; private final SnackOrderRepository orders; private final SnackRecipeItemRepository recipes; private final ProductRepository products; private final SaleRepository sales; private final CompanyRepository companies; private final CurrentUserService users; private final TenantContextService tenants; private final TenantGuard guard; private final CompanyFeatureService features; public FoodService(CourierRepository c,SnackRepository s,BeverageRepository b,SnackOrderRepository o,SnackRecipeItemRepository r,ProductRepository p,SaleRepository sr,CompanyRepository co,CurrentUserService u,TenantContextService t,TenantGuard g,CompanyFeatureService f){couriers=c;snacks=s;beverages=b;orders=o;recipes=r;products=p;sales=sr;companies=co;users=u;tenants=t;guard=g;features=f;} private TenantContext ctx(CompanyFeature f){var c=tenants.requireForUser(users.requireUserId());features.require(c.companyId(),f);guard.requireOwnerOrAdmin(c);return c;} private String clean(String s){return s==null?null:s.trim();} private BigDecimal money(BigDecimal v){return (v==null?BigDecimal.ZERO:v).setScale(2,RoundingMode.HALF_UP);}
@Transactional(readOnly=true) public List<CourierResponse> couriers(){var c=ctx(CompanyFeature.COURIERS);return couriers.findAllByCompany_IdOrderByNameAsc(c.companyId()).stream().map(CourierResponse::from).toList();} @Transactional public CourierResponse saveCourier(UUID id,CourierRequest r){var c=ctx(CompanyFeature.COURIERS);var e=id==null?Courier.create(companies.findById(c.companyId()).orElseThrow(),clean(r.name()),clean(r.phone()),r.deliveryFee()):couriers.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Motoboy"));if(id!=null)e.update(clean(r.name()),clean(r.phone()),r.deliveryFee());return CourierResponse.from(couriers.save(e));} @Transactional public void deleteCourier(UUID id){var c=ctx(CompanyFeature.COURIERS);couriers.delete(couriers.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Motoboy")));}
@Transactional(readOnly=true) public List<SnackResponse> snacks(){var c=ctx(CompanyFeature.SNACKS);return snacks.findAllByCompany_IdOrderByNameAsc(c.companyId()).stream().map(SnackResponse::from).toList();} @Transactional public SnackResponse saveSnack(UUID id,SnackRequest r){var c=ctx(CompanyFeature.SNACKS);var ins=Optional.ofNullable(r.ingredients()).orElse(List.of()).stream().map(this::clean).filter(x->x!=null&&!x.isBlank()).toList();var adds=Optional.ofNullable(r.additionals()).orElse(List.of()).stream().map(a->new SnackAdditional(clean(a.name()),a.price())).toList();var e=id==null?Snack.create(companies.findById(c.companyId()).orElseThrow(),clean(r.name()),r.price(),ins,adds):snacks.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Lanche"));if(id!=null)e.update(clean(r.name()),r.price(),ins,adds);return SnackResponse.from(snacks.save(e));} @Transactional public void deleteSnack(UUID id){var c=ctx(CompanyFeature.SNACKS);snacks.delete(snacks.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Lanche")));}
@Transactional(readOnly=true) public List<BeverageResponse> beverages(){var c=ctx(CompanyFeature.BEVERAGES);return beverages.findAllByCompany_IdOrderByNameAsc(c.companyId()).stream().map(BeverageResponse::from).toList();} @Transactional public BeverageResponse saveBeverage(UUID id,BeverageRequest r){var c=ctx(CompanyFeature.BEVERAGES);var e=id==null?Beverage.create(companies.findById(c.companyId()).orElseThrow(),clean(r.name()),r.price(),r.cost()):beverages.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Bebida"));if(id!=null)e.update(clean(r.name()),r.price(),r.cost());return BeverageResponse.from(beverages.save(e));} @Transactional public void deleteBeverage(UUID id){var c=ctx(CompanyFeature.BEVERAGES);beverages.delete(beverages.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Bebida")));}
@Transactional(readOnly=true) public List<SnackOrderResponse> orders(){var c=ctx(CompanyFeature.NOTES);return orders.findAllByCompany_IdOrderByCreatedAtDesc(c.companyId()).stream().map(SnackOrderResponse::from).toList();} @Transactional public SnackOrderResponse createOrder(SnackOrderRequest r){var c=ctx(CompanyFeature.NOTES);Courier courier=r.courierId()==null?null:couriers.findByIdAndCompany_Id(r.courierId(),c.companyId()).orElseThrow(()->nf("Motoboy"));var e=SnackOrder.create(companies.findById(c.companyId()).orElseThrow(),courier,clean(r.clientName()),clean(r.clientPhone()),clean(r.clientCity()),r.itemsText(),r.itemsTotal(),r.deliveryFee(),r.costTotal(),r.paymentMethod(),r.cashReceived());var type=type(r.serviceType()); validateTable(c.companyId(),type,r.tableNumber(),null); if(!"DELIVERY".equals(type)&&(r.courierId()!=null||r.deliveryFee().signum()!=0))throw new ApiException(HttpStatus.BAD_REQUEST,"DELIVERY_INVALID","Mesa e retirada não possuem taxa ou motoboy"); e.setService(type,r.tableNumber()); validateDiscount(r); e.setDiscount(r.discount(),r.discountReason()); return SnackOrderResponse.from(orders.save(e));}
private void validateDiscount(SnackOrderRequest r){var d=r.discount()==null?BigDecimal.ZERO:r.discount();if(d.signum()<0||d.compareTo(r.itemsTotal().add(r.deliveryFee()))>0)throw new ApiException(HttpStatus.BAD_REQUEST,"DISCOUNT_INVALID","Desconto não pode ultrapassar o subtotal e a entrega");if(r.discountReason()!=null&&r.discountReason().length()>500)throw new ApiException(HttpStatus.BAD_REQUEST,"DISCOUNT_REASON","Motivo do desconto deve ter no máximo 500 caracteres");}
private String type(String value){String v=value==null?"DELIVERY":value.toUpperCase(Locale.ROOT);if(!Set.of("DELIVERY","PICKUP","TABLE").contains(v))throw new ApiException(HttpStatus.BAD_REQUEST,"SERVICE_TYPE","Tipo de atendimento inválido");return v;}
 private void validateTable(UUID company,String type,Integer number,UUID except){if("TABLE".equals(type)){features.require(company,CompanyFeature.TABLES);if(number==null||!diningTables.existsByCompany_IdAndNumber(company,number))throw new ApiException(HttpStatus.BAD_REQUEST,"TABLE_NOT_FOUND","Mesa não cadastrada");boolean occupied=orders.findAllByCompany_IdOrderByCreatedAtDesc(company).stream().anyMatch(o->!o.getId().equals(except)&&"PENDING".equals(o.getPaymentStatus())&&number.equals(o.getTableNumber()));if(occupied)throw new ApiException(HttpStatus.CONFLICT,"TABLE_OCCUPIED","Mesa já possui comanda aberta");}else if(number!=null)throw new ApiException(HttpStatus.BAD_REQUEST,"TABLE_INVALID","Mesa somente no atendimento local");}
 @Transactional public List<Integer> tables(){var c=ctx(CompanyFeature.TABLES);if(diningTables.findAllByCompany_IdOrderByNumberAsc(c.companyId()).isEmpty()){var company=companies.findById(c.companyId()).orElseThrow();for(int n=1;n<=9;n++)diningTables.save(new DiningTable(company,n));diningTables.flush();}return diningTables.findAllByCompany_IdOrderByNumberAsc(c.companyId()).stream().map(DiningTable::getNumber).toList();}
 @Transactional public List<Integer> addTable(){var c=ctx(CompanyFeature.TABLES);tables();var all=diningTables.findAllByCompany_IdOrderByNumberAsc(c.companyId());int next=all.stream().mapToInt(DiningTable::getNumber).max().orElse(0)+1;diningTables.save(new DiningTable(companies.findById(c.companyId()).orElseThrow(),next));return tables();}
 @Transactional public SnackOrderResponse editOrder(UUID id,SnackOrderRequest r){var c=ctx(CompanyFeature.NOTES);var o=orders.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Pedido"));if("CANCELLED".equals(o.getPaymentStatus()))throw new ApiException(HttpStatus.BAD_REQUEST,"CANCELLED","Pedido cancelado");String t=type(r.serviceType());validateTable(c.companyId(),t,r.tableNumber(),id);if(!"DELIVERY".equals(t)&&(r.courierId()!=null||r.deliveryFee().signum()!=0))throw new ApiException(HttpStatus.BAD_REQUEST,"DELIVERY_INVALID","Mesa e retirada não possuem taxa ou motoboy");Courier courier=r.courierId()==null?null:couriers.findByIdAndCompany_Id(r.courierId(),c.companyId()).orElseThrow(()->nf("Motoboy"));o.revise(clean(r.clientName()),clean(r.clientPhone()),clean(r.clientCity()),courier,r.itemsText(),r.itemsTotal(),r.deliveryFee(),r.costTotal(),t,r.tableNumber());validateDiscount(r); o.setDiscount(r.discount(),r.discountReason());return SnackOrderResponse.from(orders.saveAndFlush(o));}
 @Transactional public void cancelOrder(UUID id,boolean refund){var c=ctx(CompanyFeature.NOTES);var o=orders.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Pedido"));if("PAID".equals(o.getPaymentStatus())&&!refund)throw new ApiException(HttpStatus.CONFLICT,"REFUND_REQUIRED","Confirme o estorno antes de cancelar o pedido pago");o.cancel();orders.saveAndFlush(o);}
 @Transactional public SnackOrderResponse confirmOrder(UUID id, PaymentMethod method, BigDecimal received){var c=ctx(CompanyFeature.NOTES);var o=orders.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Comanda"));if(!"PENDING".equals(o.getPaymentStatus()))throw new ApiException(HttpStatus.BAD_REQUEST,"ALREADY_PAID","Comanda já finalizada");if(method==PaymentMethod.CASH&&(received==null||received.compareTo(o.getTotal())<0))throw new ApiException(HttpStatus.BAD_REQUEST,"CASH_INSUFFICIENT","Valor recebido menor que o total");o.confirmPayment(method,received);return SnackOrderResponse.from(orders.saveAndFlush(o));} @Transactional(readOnly=true) public List<SnackOrderResponse> kitchen(){var c=ctx(CompanyFeature.KITCHEN);var zone=ZoneId.systemDefault();var today=LocalDate.now(zone);var from=today.atStartOfDay(zone).toInstant();var to=today.plusDays(1).atStartOfDay(zone).toInstant();return orders.findAllByCompany_IdAndCreatedAtBetweenOrderByCreatedAtAsc(c.companyId(),from,to).stream().filter(o->"PAID".equals(o.getPaymentStatus())&&!"DONE".equals(o.getKitchenStatus())).map(SnackOrderResponse::from).toList();} @Transactional public SnackOrderResponse kitchenStatus(UUID id,String status){var c=ctx(CompanyFeature.KITCHEN);var o=orders.findByIdAndCompany_Id(id,c.companyId()).orElseThrow(()->nf("Pedido"));o.setKitchenStatus("DONE".equalsIgnoreCase(status)?"DONE":"PENDING");return SnackOrderResponse.from(o);}
@Transactional(readOnly=true) public List<SnackCostResponse> costs(){var c=tenants.requireForUser(users.requireUserId());guard.requireOwnerOrAdmin(c);return snacks.findAllByCompany_IdOrderByNameAsc(c.companyId()).stream().map(s->cost(c.companyId(),s)).toList();} private SnackCostResponse cost(UUID companyId,Snack s){var its=recipes.findAllByCompany_IdAndSnack_Id(companyId,s.getId());var rows=its.stream().map(i->new SnackCostResponse.Item(i.getProduct().getId(),i.getProduct().getName(),i.getQuantity(),money(i.getProduct().getCostPrice()),money(i.getProduct().getCostPrice().multiply(i.getQuantity())))).toList();var cost=rows.stream().map(SnackCostResponse.Item::totalCost).reduce(BigDecimal.ZERO,BigDecimal::add);return new SnackCostResponse(s.getId(),s.getName(),s.getPrice(),money(cost),money(s.getPrice().subtract(cost)),rows);} @Transactional public SnackCostResponse saveCost(UUID snackId,SnackCostRequest req){var c=ctx(CompanyFeature.SNACK_COSTS);var snack=snacks.findByIdAndCompany_Id(snackId,c.companyId()).orElseThrow(()->nf("Lanche"));recipes.deleteAllByCompany_IdAndSnack_Id(c.companyId(),snackId);var company=companies.findById(c.companyId()).orElseThrow();for(var r:Optional.ofNullable(req.items()).orElse(List.of())){var p=products.findByIdAndCompanyId(r.productId(),c.companyId()).orElseThrow(()->nf("Produto"));recipes.save(SnackRecipeItem.create(company,snack,p,r.quantity()));}return cost(c.companyId(),snack);}
@Transactional(readOnly=true) public SnackStatsResponse stats(Instant from,Instant to){var c=ctx(CompanyFeature.SNACK_STATS);var all=orders.findAllByCompany_IdAndCreatedAtBetweenOrderByCreatedAtAsc(c.companyId(),from,to).stream().filter(o->"PAID".equals(o.getPaymentStatus())).toList();var revenue=all.stream().map(o->o.getSettledTotal()==null?o.getItemsTotal():o.getSettledTotal()).reduce(BigDecimal.ZERO,BigDecimal::add);var cost=all.stream().map(SnackOrder::getCostTotal).reduce(BigDecimal.ZERO,BigDecimal::add);var profit=revenue.subtract(cost);var margin=revenue.signum()==0?BigDecimal.ZERO:profit.multiply(BigDecimal.valueOf(100)).divide(revenue,2,RoundingMode.HALF_UP);return new SnackStatsResponse(all.size(),money(revenue),money(cost),money(profit),margin);}
@Transactional(readOnly=true) public CashSummaryResponse cash(LocalDate date){var c=ctx(CompanyFeature.CASH);var zone=ZoneId.systemDefault();var from=date.atStartOfDay(zone).toInstant();var to=date.plusDays(1).atStartOfDay(zone).toInstant();var entries=new ArrayList<CashSummaryResponse.Entry>();for(var s:sales.findAllActiveInRange(c.companyId(),from,to)){if(s.getPaymentType()==SalePaymentType.PRAZO)continue;entries.add(new CashSummaryResponse.Entry("VENDA","Venda #"+s.getNumber(),s.getPaymentMethod(),s.getTotal(),s.getSoldAt().toString()));}for(var o:orders.findAllByCompany_IdAndCreatedAtBetweenOrderByCreatedAtAsc(c.companyId(),from,to))if("PAID".equals(o.getPaymentStatus()))entries.add(new CashSummaryResponse.Entry("LANCHE","Pedido - "+o.getClientName(),o.getPaymentMethod(),(o.getSettledTotal()==null?o.getTotal():o.getSettledTotal()),o.getCreatedAt().toString()));for(var o:orders.findAllByCompany_IdOrderByCreatedAtDesc(c.companyId()))if(o.getRefundedAt()!=null&&!o.getRefundedAt().isBefore(from)&&o.getRefundedAt().isBefore(to))entries.add(new CashSummaryResponse.Entry("ESTORNO","Estorno - "+o.getClientName(),o.getPaymentMethod(),(o.getSettledTotal()==null?o.getTotal():o.getSettledTotal()).negate(),o.getRefundedAt().toString()));BigDecimal pix=sum(entries,PaymentMethod.PIX),cc=sum(entries,PaymentMethod.CREDIT_CARD),dc=sum(entries,PaymentMethod.DEBIT_CARD),cash=sum(entries,PaymentMethod.CASH);return new CashSummaryResponse(date,money(pix.add(cc).add(dc).add(cash)),money(pix),money(cc),money(dc),money(cash),entries);} private BigDecimal sum(List<CashSummaryResponse.Entry> e,PaymentMethod m){return e.stream().filter(x->x.method()==m).map(CashSummaryResponse.Entry::amount).reduce(BigDecimal.ZERO,BigDecimal::add);}
@Transactional(readOnly=true) public CourierReportResponse report(){var c=ctx(CompanyFeature.COURIERS);var all=orders.findAllByCompany_IdOrderByCreatedAtDesc(c.companyId());Map<UUID,List<SnackOrder>> by=new LinkedHashMap<>();all.stream().filter(o->o.getCourier()!=null).forEach(o->by.computeIfAbsent(o.getCourier().getId(),k->new ArrayList<>()).add(o));var rows=by.values().stream().map(v->new CourierReportResponse.Row(v.get(0).getCourier().getId(),v.get(0).getCourier().getName(),v.size(),v.stream().map(SnackOrder::getDeliveryFee).reduce(BigDecimal.ZERO,BigDecimal::add))).toList();return new CourierReportResponse(rows.stream().mapToLong(CourierReportResponse.Row::deliveries).sum(),rows.stream().map(CourierReportResponse.Row::cost).reduce(BigDecimal.ZERO,BigDecimal::add),rows);} private ApiException nf(String x){return new ApiException(HttpStatus.NOT_FOUND,"NOT_FOUND",x+" não encontrado.");}}
